#!/usr/bin/env bash
set -euo pipefail
umask 077
# Belial A4 FIX3: PAPER/shadow only. Solana transaction v1 read compatibility.
MODE="${1:-}"
if [ "$#" -gt 1 ] || { [ -n "$MODE" ] && [ "$MODE" != "--verificar-pacote" ]; }; then
  echo 'Uso: bash BELIAL_A4_90M_FIX3_EXECUTAR.sh [--verificar-pacote]' >&2
  exit 2
fi
command -v python3 >/dev/null || { echo 'Python 3 não encontrado. Nada foi instalado.' >&2; exit 2; }
if [ "$(id -u)" -eq 0 ] && [ "$MODE" != "--verificar-pacote" ]; then
  echo 'Execute como usuário normal, sem sudo/root.' >&2
  exit 2
fi
TMP="$(mktemp -d -t belial-a4-fix3-XXXXXX)"
cleanup(){ rm -rf -- "$TMP"; }
trap cleanup EXIT
base64 -d > "$TMP/payload.tar.gz" <<'BELIAL_A4_PAYLOAD'
